import{_ as t,o as r,c as a,a5 as l}from"./chunks/framework.Bt0SrEfo.js";const d=JSON.parse('{"title":"TypeScript 学习资源","description":"","frontmatter":{},"headers":[],"relativePath":"前端/typescript/16-resources.md","filePath":"前端/typescript/16-resources.md","lastUpdated":1792683759000}'),o={name:"前端/typescript/16-resources.md"};function i(s,e,n,c,p,h){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="typescript-学习资源" tabindex="-1">TypeScript 学习资源 <a class="header-anchor" href="#typescript-学习资源" aria-label="Permalink to &quot;TypeScript 学习资源&quot;">​</a></h1><h2 id="一、官方文档-必读" tabindex="-1">一、官方文档(必读) <a class="header-anchor" href="#一、官方文档-必读" aria-label="Permalink to &quot;一、官方文档(必读)&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/docs/" target="_blank" rel="noreferrer">TypeScript 官方文档(英文)</a>——最权威,新特性最先在这里发</li><li><a href="https://www.tslang.cn/" target="_blank" rel="noreferrer">TypeScript 中文文档</a>——社区翻译,基本同步</li></ul><p>官方文档从入门到高级类型全覆盖,<strong>每个章节都有可运行的 playground 例子</strong>——遇到不确定的类型行为直接打开 <a href="https://www.typescriptlang.org/play" target="_blank" rel="noreferrer">TypeScript Playground</a> 试一下。</p><hr><h2 id="二、推荐书" tabindex="-1">二、推荐书 <a class="header-anchor" href="#二、推荐书" aria-label="Permalink to &quot;二、推荐书&quot;">​</a></h2><ul><li><strong>《TypeScript 编程》(Programming TypeScript)</strong>——O&#39;Reilly 出品,入门 + 进阶,内容扎实</li><li><strong>《Effective TypeScript》</strong>——62 个具体实践,适合已经会 TS 想&quot;用好&quot;的人</li></ul><hr><h2 id="三、练习平台" tabindex="-1">三、练习平台 <a class="header-anchor" href="#三、练习平台" aria-label="Permalink to &quot;三、练习平台&quot;">​</a></h2><h3 id="_3-1-type-challenges-强烈推荐" tabindex="-1">3.1 type-challenges(强烈推荐) <a class="header-anchor" href="#_3-1-type-challenges-强烈推荐" aria-label="Permalink to &quot;3.1 type-challenges(强烈推荐)&quot;">​</a></h3><p><a href="https://github.com/type-challenges/type-challenges" target="_blank" rel="noreferrer">github.com/type-challenges/type-challenges</a></p><p>从简单到地狱级别的类型体操题集。面试遇到 &quot;Pick 实现&quot;、&quot;DeepReadonly&quot; 时这就是复习利器。<strong>前端面试 TS 高频题基本都来自这里</strong>。</p><p>推荐刷到中等难度(medium)就足够应付面试。</p><h3 id="_3-2-typescript-exercises" tabindex="-1">3.2 TypeScript Exercises <a class="header-anchor" href="#_3-2-typescript-exercises" aria-label="Permalink to &quot;3.2 TypeScript Exercises&quot;">​</a></h3><p><a href="https://typescript-exercises.github.io/" target="_blank" rel="noreferrer">typescript-exercises.github.io</a></p><p>偏基础,把 JS 重写成 TS 的练习。</p><hr><h2 id="四、优质博客-视频" tabindex="-1">四、优质博客/视频 <a class="header-anchor" href="#四、优质博客-视频" aria-label="Permalink to &quot;四、优质博客/视频&quot;">​</a></h2><ul><li><strong>TypeScript Deep Dive</strong>(中文:<a href="https://jkchao.gitbook.io/typescript-book/" target="_blank" rel="noreferrer">jkchao.gitbook.io/typescript-book</a>)——开源免费电子书,中文版质量很好</li><li><strong>Matt Pocock</strong>(Twitter/@mattpocockUk)——TS 团队外最大的 KOL,博客和视频质量极高</li><li><strong>Titian Cernicova-Dragomir</strong>(TS 团队核心成员)——<a href="https://kentcdodds.com/blog" target="_blank" rel="noreferrer">博客</a> 关于类型设计的文章</li></ul><hr><h2 id="五、playground-与工具" tabindex="-1">五、Playground 与工具 <a class="header-anchor" href="#五、playground-与工具" aria-label="Permalink to &quot;五、Playground 与工具&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/play" target="_blank" rel="noreferrer">TypeScript Playground</a>——浏览器内运行 TS,支持多版本切换</li><li><a href="https://replit.com/languages/typescript" target="_blank" rel="noreferrer">ts-repl</a>——Replit 的在线 TS REPL</li><li>VS Code 内置 TS Server,<strong>不需要任何插件就能获得最好的 TS 体验</strong></li></ul><hr><h2 id="六、社区" tabindex="-1">六、社区 <a class="header-anchor" href="#六、社区" aria-label="Permalink to &quot;六、社区&quot;">​</a></h2><ul><li>TypeScript GitHub: <a href="https://github.com/microsoft/TypeScript" target="_blank" rel="noreferrer">github.com/microsoft/TypeScript</a>——发 issue、提 PR、读 RFC</li><li>Stack Overflow <code>typescript</code> tag——90% 的常见问题这里都有答案</li></ul><h2 id="面试常考" tabindex="-1">面试常考 <a class="header-anchor" href="#面试常考" aria-label="Permalink to &quot;面试常考&quot;">​</a></h2><h3 id="q1-ts-学习路径推荐" tabindex="-1">Q1:TS 学习路径推荐? <a class="header-anchor" href="#q1-ts-学习路径推荐" aria-label="Permalink to &quot;Q1:TS 学习路径推荐?&quot;">​</a></h3><p><strong>答</strong>:</p><ol><li>基础类型 / 接口 / 联合类型</li><li>泛型 / 工具类型</li><li>条件类型 / infer / 模板字面量</li><li>实战:React / Vue 组件类型</li><li>类型编程:zod / io-ts / type-challenges</li></ol><ul><li>周期:2-3 个月系统学习(边做项目边查类型)</li></ul><h3 id="q2-type-challenges-怎么刷" tabindex="-1">Q2:type-challenges 怎么刷? <a class="header-anchor" href="#q2-type-challenges-怎么刷" aria-label="Permalink to &quot;Q2:type-challenges 怎么刷?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li>GitHub 仓库:几万道类型挑战题</li><li>分难度:Easy / Medium / Hard / Extreme</li><li>实战:Hard 级别 50% 都能独立解决 = 高级 TS 工程师</li><li>重点关注:<code>Pick</code> / <code>Omit</code> / <code>DeepReadonly</code> / <code>Promise.all</code> 推断</li></ul><h3 id="q3-ts-工程师级别划分" tabindex="-1">Q3:TS 工程师级别划分? <a class="header-anchor" href="#q3-ts-工程师级别划分" aria-label="Permalink to &quot;Q3:TS 工程师级别划分?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>初级</strong>:基础类型 / interface / 泛型使用</li><li><strong>中级</strong>:Partial / Pick / Omit / 联合类型</li><li><strong>高级</strong>:条件类型 / infer / 模板字面量 / 类型守卫</li><li><strong>资深</strong>:类型编程(zod / type-challenges 难题);库作者级别</li><li>区分:看是否理解<strong>类型即函数</strong></li></ul><h3 id="q4-推荐学习资源" tabindex="-1">Q4:推荐学习资源? <a class="header-anchor" href="#q4-推荐学习资源" aria-label="Permalink to &quot;Q4:推荐学习资源?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>官方手册</strong>:<code>typescriptlang.org</code> 必读 Handbook</li><li><strong>Type Challenges</strong>:<code>github.com/type-challenges/type-challenges</code></li><li><strong>type-level-typescript</strong>:<code>type-level-typescript.org</code>(交互式)</li><li><strong>Matt Pocock</strong>:<code>totaltypescript.com</code>(实战向,付费)</li><li><strong>书籍</strong>:<code>Programming TypeScript</code>(O&#39;Reilly)</li></ul>',39)])])}const u=t(o,[["render",i]]);export{d as __pageData,u as default};
